class Solution:
    def minFlips(self, grid):
        n, m = len(grid), len(grid[0])
        base = ones = 0
        quad2 = quad13 = mixedFree = pairToggle = center = False
        for i in range((n + 1) // 2):
            for j in range((m + 1) // 2):
                cells = {(i, j), (n-1-i, j), (i, m-1-j), (n-1-i, m-1-j)}
                c = sum(grid[a][b] for a, b in cells)
                if len(cells) == 4:
                    base += min(c, 4 - c)
                    ones += 4 if c >= 2 else 0
                    if c == 2: quad2 = True
                    if c in (1, 3): quad13 = True
                elif len(cells) == 2:
                    base += min(c, 2 - c)
                    if c == 1:
                        mixedFree = True
                    else:
                        pairToggle = True
                        ones += c
                else:
                    ones += c
                    center = True
        r = ones % 4
        if r == 0: return base
        if r == 2:
            if mixedFree or quad2: return base
            if quad13 or pairToggle: return base + 2
            return -1
        return base + 1 if center else -1

